   549  Elf *
   550  internal_function
   551  __libelf_read_mmaped_file (int fildes, void *map_address,  int64_t offset,
   552                             size_t maxsize, Elf_Cmd cmd, Elf *parent)
   553  {
   554    /* We have to find out what kind of file this is.  We handle ELF
   555       files and archives.  To find out what we have we must look at the
   556       header.  The header for an ELF file is EI_NIDENT bytes in size,
   557       the header for an archive file SARMAG bytes long.  */
   558    unsigned char *e_ident = (unsigned char *) map_address + offset;
   559
   560    /* See what kind of object we have here.  */
   561    Elf_Kind kind = determine_kind (e_ident, maxsize);
   562
   563    switch (kind)
   564      {
   565      case ELF_K_ELF:
   566        return file_read_elf (fildes, map_address, e_ident, offset, maxsize,
   567                              cmd, parent);
   568
   569      case ELF_K_AR:
   570        return file_read_ar (fildes, map_address, offset, maxsize, cmd, parent);
   571
   572      default:
   573        break;
   574      }
   575
   576    /* This case is easy.  Since we cannot do anything with this file
   577       create a dummy descriptor.  */
   578    return allocate_elf (fildes, map_address, offset, maxsize, cmd, parent,
   579                         ELF_K_NONE, 0);
   580  }
