   583  static Elf *
   584  read_unmmaped_file (int fildes, int64_t offset, size_t maxsize, Elf_Cmd cmd,
   585                      Elf *parent)
   586  {
   587    /* We have to find out what kind of file this is.  We handle ELF
   588       files and archives.  To find out what we have we must read the
   589       header.  The identification header for an ELF file is EI_NIDENT
   590       bytes in size, but we read the whole ELF header since we will
   591       need it anyway later.  For archives the header in SARMAG bytes
   592       long.  Read the maximum of these numbers.
   593
   594       XXX We have to change this for the extended `ar' format some day.
   595
   596       Use a union to ensure alignment.  We might later access the
   597       memory as a ElfXX_Ehdr.  */
   598    union
   599    {
   600      Elf64_Ehdr ehdr;
   601      unsigned char header[MAX (sizeof (Elf64_Ehdr), SARMAG)];
   602    } mem;
   603
   604    /* Read the head of the file.  */
   605    ssize_t nread = pread_retry (fildes, mem.header,
   606                                 MIN (MAX (sizeof (Elf64_Ehdr), SARMAG),
   607                                      maxsize),
   608                                 offset);
   609    if (unlikely (nread == -1))
   610      {
   611        /* We cannot even read the head of the file.  Maybe FILDES is associated
   612           with an unseekable device.  This is nothing we can handle.  */
   613        __libelf_seterrno (ELF_E_INVALID_FILE);
   614        return NULL;
   615      }
   616
   617    /* See what kind of object we have here.  */
   618    Elf_Kind kind = determine_kind (mem.header, nread);
   619
   620    switch (kind)
   621      {
   622      case ELF_K_AR:
   623        return file_read_ar (fildes, NULL, offset, maxsize, cmd, parent);
   624
   625      case ELF_K_ELF:
   626        /* Make sure at least the ELF header is contained in the file.  */
   627        if ((size_t) nread >= (mem.header[EI_CLASS] == ELFCLASS32
   628                               ? sizeof (Elf32_Ehdr) : sizeof (Elf64_Ehdr)))
   629          return file_read_elf (fildes, NULL, mem.header, offset, maxsize, cmd,
   630                                parent);
   631        FALLTHROUGH;
   632
   633      default:
   634        break;
   635      }
   636
   637    /* This case is easy.  Since we cannot do anything with this file
   638       create a dummy descriptor.  */
   639    return allocate_elf (fildes, NULL, offset, maxsize, cmd, parent,
   640                         ELF_K_NONE, 0);
   641  }
